import django
from django.conf import settings

settings.configure(
    DEBUG=True,
    DATABASES={},
    INSTALLED_APPS=["django.contrib.contenttypes", "django.contrib.auth"],
    CACHES={
        "default": {"BACKEND": "django.core.cache.backends.locmem.LocMemCache"},
    },
    USE_TZ=True,
)
django.setup()

from django.core.cache import cache  # noqa: E402
from django.core.cache.backends.base import DEFAULT_TIMEOUT  # noqa: E402


class Boom(Exception):
    pass


async def run_once(seed):
    rng = random.Random(seed)
    await cache.aclear()
    cache._aget_or_set_in_flight.clear()

    versions = [1, 2]
    gates = {v: asyncio.Event() for v in versions}
    calls = {v: 0 for v in versions}
    # External writer state per version
    ext_values = {v: None for v in versions}

    async def make_default(v):
        calls[v] += 1
        await gates[v].wait()
        if rng.random() < 0.2:
            raise Boom(v)
        return f"gen-{v}"

    tasks = []

    async def participant(v):
        try:
            return await cache.aget_or_set(
                "key", lambda v=v: make_default(v), version=v
            )
        except Boom:
            return Boom
        except asyncio.CancelledError:
            return CancelledError

    # launch random participants for each version
    for v in versions:
        for _ in range(rng.randint(1, 4)):
            tasks.append((v, asyncio.create_task(participant(v))))
            await asyncio.sleep(0)

    # random external ops / cancels / gate sets
    pending = list(tasks)
    while pending or not all(g.is_set() for g in gates.values()):
        await asyncio.sleep(rng.random() * 0.002)
        choice = rng.random()
        if choice < 0.25 and pending:
            v, t = pending.pop(rng.randrange(len(pending)))
            t.cancel()
        elif choice < 0.45:
            v = rng.choice(versions)
            if rng.random() < 0.5:
                ext_values[v] = f"ext-{v}-{rng.randrange(1000)}"
                await cache.aset("key", ext_values[v], version=v)
            else:
                await cache.adelete("key", version=v)
                ext_values[v] = None
        elif choice < 0.55:
            # random plain read
            v = rng.choice(versions)
            await cache.aget("key", version=v)
        else:
            for v in versions:
                if not gates[v].is_set() and rng.random() < 0.3:
                    gates[v].set()
        pending = [(v, t) for v, t in pending if not t.done()]
        if all(g.is_set() for g in gates.values()) and not pending:
            break

    for g in gates.values():
        g.set()
    for _, t in tasks:
        t.cancel()
    results = {}
    for v, t in tasks:
        with warnings.catch_warnings():
            warnings.simplefilter("error")
            try:
                r = await t
            except asyncio.CancelledError:
                r = CancelledError
            except Boom:
                r = Boom
            except Warning as w:
                raise AssertionError(f"warning raised: {w}")
        results.setdefault(v, []).append(r)

    # Let all cleanup callbacks run.
    await asyncio.sleep(0.02)

    # Invariant 1: registry must be empty after everyone unwound.
    assert cache._aget_or_set_in_flight == {}, cache._aget_or_set_in_flight

    # Invariant 2: per version, everyone who got a value (not cancelled / not
    # the shared failure) agrees on one single value, and that value is what
    # the cache holds now or what the generation produced.
    for v in versions:
        vals = {r for r in results.get(v, []) if r not in (CancelledError, Boom)}
        assert len(vals) <= 1, (v, vals)
        cached = await cache.aget("key", version=v)
        if vals:
            (val,) = vals
            # The committed value must equal the observed value if present.
            if cached is not None:
                assert cached == val, (v, cached, val)
        # Calls per version bounded: at least 1, and extra generations only
        # happen after full cancellation (participants==0 abandonment).
        assert calls[v] >= 1, (v, calls)


async def main():
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 500
    for seed in range(n):
        await run_once(seed)
        if seed % 50 == 0:
            print("seed", seed, "OK", flush=True)
    print(f"all {n} iterations OK")


if __name__ == "__main__":
    asyncio.run(main())

